  const tld = fl.book.tlds[k];
  if (tld.$ === "ADT") {
    return "null";
  }
  const intr = intr_of(fl, k, true)?.JS ?? null;
  if (intr === null && !fun_runs(tld)) {
    die("a live call into the law " + Bend.name_key(k));
