    i : V.Instance <- V.Entry.create_instance(e, V.InstanceConfig.headless())
    ps : List<V.PhysicalDevice> <- V.Instance.enumerate_physical_devices(i)
    infos : List<V.PhysicalDeviceInfo> <- V.Instance.describe_all(i, ps)
