typedef struct {
  Display* dpy;
  Window   win;
  Atom     del;
  XImage*  img;
  u32      n;
  u32      cap;
  u32*     evs;
  u32      grab;
  u64      period;
} BendWin;

#endif

#ifdef CID(Window.open)

